<?php
namespace App\Http\Controllers\Sales;use App\Http\Controllers\Controller;use App\Models\{CorporateAccount,GroupReservation,HotelEvent,SalesQuotation,TravelAgent};use Illuminate\Http\Request;use Illuminate\Support\Str;
class QuotationController extends Controller{public function index(){ $p=auth()->user()->property_id;return view('sales.quotations',['quotations'=>SalesQuotation::where('property_id',$p)->with('company','agent','items')->latest()->paginate(40),'companies'=>CorporateAccount::where('property_id',$p)->where('status','active')->get(),'agents'=>TravelAgent::where('property_id',$p)->where('status','active')->get(),'events'=>HotelEvent::where('property_id',$p)->latest()->limit(50)->get(),'groups'=>GroupReservation::where('property_id',$p)->latest()->limit(50)->get()]);}public function store(Request $r){$d=$r->validate(['customer_type'=>'required|in:corporate,agent,event,group,other','corporate_account_id'=>'nullable|exists:corporate_accounts,id','travel_agent_id'=>'nullable|exists:travel_agents,id','hotel_event_id'=>'nullable|exists:hotel_events,id','group_reservation_id'=>'nullable|exists:group_reservations,id','customer_name'=>'required|max:180','customer_email'=>'nullable|email','valid_until'=>'nullable|date','terms'=>'nullable|string','item_description'=>'required|array|min:1','item_description.*'=>'required|string','quantity'=>'required|array','quantity.*'=>'required|numeric|min:0.001','unit_price'=>'required|array','unit_price.*'=>'required|numeric|min:0','tax_rate'=>'nullable|array','tax_rate.*'=>'nullable|numeric|min:0|max:100','discount_total'=>'nullable|numeric|min:0']);$subtotal=0;$tax=0;$items=[];foreach($d['item_description'] as $i=>$desc){$q=(float)$d['quantity'][$i];$u=(float)$d['unit_price'][$i];$rate=(float)($d['tax_rate'][$i]??0);$net=$q*$u;$lineTax=$net*$rate/100;$subtotal+=$net;$tax+=$lineTax;$items[]=['description'=>$desc,'quantity'=>$q,'unit_price'=>$u,'tax_rate'=>$rate,'line_total'=>$net+$lineTax];}$discount=(float)($d['discount_total']??0);$quote=SalesQuotation::create(['property_id'=>auth()->user()->property_id,'quotation_no'=>'QUO-'.now()->format('YmdHis').'-'.Str::upper(Str::random(4)),'customer_type'=>$d['customer_type'],'corporate_account_id'=>$d['corporate_account_id']??null,'travel_agent_id'=>$d['travel_agent_id']??null,'hotel_event_id'=>$d['hotel_event_id']??null,'group_reservation_id'=>$d['group_reservation_id']??null,'customer_name'=>$d['customer_name'],'customer_email'=>$d['customer_email']??null,'quotation_date'=>today(),'valid_until'=>$d['valid_until']??null,'status'=>'draft','subtotal'=>$subtotal,'discount_total'=>$discount,'tax_total'=>$tax,'grand_total'=>max(0,$subtotal+$tax-$discount),'terms'=>$d['terms']??null,'created_by'=>auth()->id()]);$quote->items()->createMany($items);return back()->with('success','Quotation '.$quote->quotation_no.' created.');}public function status(Request $r,SalesQuotation $quotation){$r->validate(['status'=>'required|in:draft,sent,accepted,rejected,expired,cancelled']);abort_unless($quotation->property_id===auth()->user()->property_id,403);$quotation->update(['status'=>$r->status]);return back()->with('success','Quotation status updated.');}}
